const isCancelled = (item) => {
  const status = String(item?.status || item?.state || "").trim().toLowerCase();
  return item?.isCancelled === true
    || item?.cancelled === true
    || item?.canceled === true
    || status === "cancelled"
    || status === "canceled"
    || status === "cancel";
};

const byKey = new Map();

list.forEach((item, index) => {
  const client = item?.client;
  const clientId = String(client?.id || "").trim();
  if (isCancelled(item) || !clientId) return;

  const key = clientId ? `client:${clientId}` : `booking:${item?.id || index}`;
  if (byKey.has(key)) return;

  byKey.set(key, {
    id: item.id,
    spot: item.spot,
    isCancelled: false,
    client: {
      id: clientId,
      firstName: client.firstName,
      lastName: client.lastName,
